import{_ as a,a0 as o,w as r,s as i,ao as l,I as p,x as n,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Adding User Accounts In Ubuntu","title":"每日Ubuntu小技巧——在Ubuntu中添加用户","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Adding User Accounts In Ubuntu.md","filePath":"[post].md"}'),b={name:"201311/Daily Ubuntu Tips – Adding User Accounts In Ubuntu.md"};function d(g,t,U,m,w,T){const u=o("Link");return r(),i("div",null,[t[11]||(t[11]=l('<h1 id="每日ubuntu小技巧——在ubuntu中添加用户" tabindex="-1">每日Ubuntu小技巧——在Ubuntu中添加用户 <a class="header-anchor" href="#每日ubuntu小技巧——在ubuntu中添加用户" aria-label="Permalink to “每日Ubuntu小技巧——在Ubuntu中添加用户”">​</a></h1><p>Ubuntu是一個多用户操作系統。多用户操作系統意味着多個用户可以通過獨立的、個人的HOME文件夾，文件和設置訪問計算機。用户<strong>A</strong>可以登錄並修改他/她自己的配置文件而不會影響用户<strong>B</strong>的配置文件。</p><p>因此，你可以為每一個可能使用你家裏電腦的用户創建一個獨立的賬户，而不是僅僅為所有人創建一個共享的賬户。本文將展示使用Ubuntu時如何實現這一點。</p><p>為了獲得上面所説的那樣的獨立賬户，首先點擊長條菜單欄上的齒輪圖標，然後點擊系統設置。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable4.png" alt=""></p><p>當如圖所示的窗口打開後，點擊屏幕下方的“<strong>用户賬户（User Accounts）</strong>”，如下圖所示。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu.png" alt=""></p><p>要添加用户到你的Ubuntu需要管理員權限，請在添加賬户前點擊解鎖（Unlock)。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu1.png" alt=""></p><p>然後，點擊加號（ + ）按鈕來創建用户賬户。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu2.png" alt=""></p><p>創建用户時有兩種基本的賬户類型： <strong>標準用户</strong> 和 <strong>管理員</strong> 。管理員權限用户有權限刪除用户，安裝軟件和驅動，修改日期和時間，或者進行一些可能使計算機不穩定的操作。</p><p>標準用户不能進行這些操作。他/她只能夠修改自己的個人設置裏面的東西。</p><p>輸入用户全名時，系統將根據全名自動選擇用户名。你可以保留自動生成的用户名，也可以根據需要修改用户名。完成後，點擊<strong>創建（Create)</strong>來創建賬户。</p><p>默認情況下，剛創建的賬户是不可用的，除非給他設置或修改了密碼。要想讓賬户可用，點擊賬户的不可用按鈕，然後輸入密碼。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu3.png" alt=""></p><p>如果你想要用户自動登錄而不用輸入密碼，你可以在設置他/她登錄密碼的時候選擇下拉選項中的自動登錄。</p><h2 id="enjoy" tabindex="-1">Enjoy! <a class="header-anchor" href="#enjoy" aria-label="Permalink to “Enjoy!”">​</a></h2>',18)),p("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-user-accounts-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-user-accounts-ubuntu/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原創翻譯，",-1)),e(u,{href:"http://linux.cn/"},{default:s(()=>[...t[3]||(t[3]=[n("Linux中國",-1)])]),_:1}),t[6]||(t[6]=n(" 榮譽推出",-1))]),p("p",null,[t[9]||(t[9]=n("譯者：",-1)),e(u,{href:"https://github.com/scusjs"},{default:s(()=>[...t[7]||(t[7]=[n("SCUSJS",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),e(u,{href:"https://github.com/jasminepeng"},{default:s(()=>[...t[8]||(t[8]=[n("jasmiepeng",-1)])]),_:1})])])}const k=a(b,[["render",d]]);export{C as __pageData,k as default};
